export interface ConversionRequest {
  fromUnit: string;
  toUnit: string;
  value: number;
}

export interface ConversionResult {
  convertedValue: number;
  fromUnit: string;
  toUnit: string;
  value: number;
}

export function handleConversion(request: ConversionRequest): ConversionResult {
  const conversions: { [key: string]: { [key: string]: number } } = {
    length: {
      m: 1,
      cm: 0.01,
      mm: 0.001,
      in: 0.0254,
      ft: 0.3048,
      yd: 0.9144,
      km: 1000,
    },
    weight: {
      kg: 1,
      g: 0.001,
      mg: 0.000001,
      lb: 0.453592,
      oz: 0.0283467,
    },
    temperature: {
      celsius: 1,
      fahrenheit: 1.8,
      kelvin: 1,
    },
    volume: {
      l: 1,
      ml: 0.001,
      gal: 3.78541,
      qt: 0.946353,
      pint: 0.473176,
    },
  };

  const fromUnit = conversions[request.fromUnit];
  const toUnit = conversions[request.toUnit];

  if (!fromUnit || !toUnit) {
    throw new Error('Invalid conversion units');
  }

  const convertedValue = request.value * fromUnit / toUnit;

  return {
    convertedValue,
    fromUnit: request.fromUnit,
    toUnit: request.toUnit,
    value: request.value,
  };
}

import { ConversionRequest, ConversionResult, handleConversion } from '../core-engine/core-engine.ts';

export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="app">
      <div class="row">
        <button class="btn" onclick="convertUnits()">▶ Convert</button>
      </div>
      <div class="row">
        <label for="fromUnit">From Unit:</label>
        <select id="fromUnit" onchange="convertUnits()">
          <option value="m">Meter (m)</option>
          <option value="cm">Centimeter (cm)</option>
          <option value="mm">Millimeter (mm)</option>
          <option value="in">Inch (in)</option>
          <option value="ft">Foot (ft)</option>
          <option value="yd">Yard (yd)</option>
          <option value="km">Kilometer (km)</option>
        </select>
      </div>
      <div class="row">
        <label for="toUnit">To Unit:</label>
        <select id="toUnit" onchange="convertUnits()">
          <option value="m">Meter (m)</option>
          <option value="cm">Centimeter (cm)</option>
          <option value="mm">Millimeter (mm)</option>
          <option value="in">Inch (in)</option>
          <option value="ft">Foot (ft)</option>
          <option value="yd">Yard (yd)</option>
          <option value="km">Kilometer (km)</option>
        </select>
      </div>
      <div class="row">
        <label for="value">Value:</label>
        <input id="value" type="number" placeholder="Enter value" onchange="convertUnits()">
      </div>
      <div class="row">
        <label for="result">Converted Value:</label>
        <input id="result" type="text" placeholder="Converted value" readonly>
      </div>
    </div>
  `;

  const fromUnitSelect = document.getElementById('fromUnit') as HTMLSelectElement;
  const toUnitSelect = document.getElementById('toUnit') as HTMLSelectElement;
  const valueInput = document.getElementById('value') as HTMLInputElement;
  const resultDisplay = document.getElementById('result') as HTMLInputElement;

  function convertUnits() {
    const fromUnit = fromUnitSelect.value;
    const toUnit = toUnitSelect.value;
    const value = parseFloat(valueInput.value);

    if (isNaN(value)) {
      resultDisplay.value = 'Invalid value';
      return;
    }

    const conversions: { [key: string]: { [key: string]: number } } = {
      length: {
        m: 1,
        cm: 0.01,
        mm: 0.001,
        in: 0.0254,
        ft: 0.3048,
        yd: 0.9144,
        km: 1000,
      },
      weight: {
        kg: 1,
        g: 0.001,
        mg: 0.000001,
        lb: 0.453592,
        oz: 0.0283467,
      },
      temperature: {
        celsius: 1,
        fahrenheit: 1.8,
        kelvin: 1,
      },
      volume: {
        l: 1,
        ml: 0.001,
        gal: 3.78541,
        qt: 0.946353,
        pint: 0.473176,
      },
    };

    const fromConversion = conversions[fromUnit];
    const toConversion = conversions[toUnit];

    if (!fromConversion || !toConversion) {
      resultDisplay.value = 'Invalid conversion units';
      return;
    }

    const convertedValue = value * fromConversion / toConversion;
    resultDisplay.value = convertedValue.toString();
  }
}

